independent_native_and_hash_check.cmd:
$ErrorActionPreference='Stop'
$manifest=Get-Content -Raw artifacts/rp4_daily_collector_setup/public_manifest.json | ConvertFrom-Json -AsHashtable
$count=0
foreach ($name in @('outputs_sha256','source_pins_sha256')) { foreach ($entry in $manifest[$name].GetEnumerator()) { $actual=(Get-FileHash -LiteralPath $entry.Key -Algorithm SHA256).Hash.ToLowerInvariant(); if ($actual -ne $entry.Value) { throw "COLLECTOR_HASH_MISMATCH:$($entry.Key)" }; $count++ } }
foreach ($script in @('artifacts/rp4_daily_collector_code/launch.ps1','artifacts/rp4_daily_collector_code/register_disabled.ps1')) { $parseTokens=$null; $parseErrors=$null; [void][System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path -LiteralPath $script),[ref]$parseTokens,[ref]$parseErrors); if ($parseErrors.Count -ne 0) { throw 'POWERSHELL_PARSE_FAILED' } }
$task=Get-ScheduledTask -TaskName 'OptionsVolatility-Daily-Collection'
if ($task.State -ne 'Disabled' -or $task.Settings.Enabled -or $task.Settings.AllowDemandStart -or @($task.Triggers | Where-Object Enabled).Count -ne 0) { throw 'TASK_NOT_DISABLED' }
if (Test-Path -LiteralPath 'private-input/21d33a47d00d81c7f6df') { throw 'UNEXPECTED_DATA_ROOT' }
[pscustomobject]@{Status='PASS';HashChecks=$count;PowerShellParsed=2;TaskState=[string]$task.State;TaskEnabled=$task.Settings.Enabled;TriggerEnabled=$task.Triggers[0].Enabled;AllowDemandStart=$task.Settings.AllowDemandStart;DataRootExists=$false} | ConvertTo-Json
